{
  "items": [
    {
      "name": "Polynomial.taylor_taylor",
      "module_name": "Mathlib.Algebra.Polynomial.Taylor",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommSemiring R] (f : Polynomial R) (r s : R),\n  (Polynomial.taylor r) ((Polynomial.taylor s) f) = (Polynomial.taylor (r + s)) f"
    },
    {
      "name": "Polynomial.taylor",
      "module_name": "Mathlib.Algebra.Polynomial.Taylor",
      "kind": "definition",
      "type": "{R : Type u_1} → [inst : Semiring R] → R → Polynomial R →ₗ[R] Polynomial R"
    },
    {
      "name": "Polynomial.taylor_apply",
      "module_name": "Mathlib.Algebra.Polynomial.Taylor",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] (r : R) (f : Polynomial R),\n  (Polynomial.taylor r) f = f.comp (Polynomial.X + Polynomial.C r)"
    },
    {
      "name": "translate_translate",
      "module_name": "Mathlib.Algebra.Group.Translate",
      "kind": "theorem",
      "type": "∀ {α : Type u_2} {G : Type u_5} [inst : AddCommGroup G] (a b : G) (f : G → α),\n  translate a (translate b f) = translate (a + b) f"
    },
    {
      "name": "Polynomial.taylorAlgHom",
      "module_name": "Mathlib.Algebra.Polynomial.Taylor",
      "kind": "definition",
      "type": "{R : Type u_1} → [inst : CommSemiring R] → R → Polynomial R →ₐ[R] Polynomial R"
    },
    {
      "name": "Polynomial.map_taylor",
      "module_name": "Mathlib.Algebra.Polynomial.Taylor",
      "kind": "theorem",
      "type": "∀ {R : Type u_2} {S : Type u_3} [inst : Semiring R] [inst_1 : Semiring S] (p : Polynomial R) (r : R) (f : R →+* S),\n  Polynomial.map f ((Polynomial.taylor r) p) = (Polynomial.taylor (f r)) (Polynomial.map f p)"
    },
    {
      "name": "Polynomial.taylorEquiv",
      "module_name": "Mathlib.Algebra.Polynomial.Taylor",
      "kind": "definition",
      "type": "{R : Type u_1} → [inst : CommRing R] → R → Polynomial R ≃ₐ[R] Polynomial R"
    },
    {
      "name": "HasFTaylorSeriesUpToOn.comp",
      "module_name": "Mathlib.Analysis.Calculus.ContDiff.FaaDiBruno",
      "kind": "theorem",
      "type": "∀ {𝕜 : Type u_1} [inst : NontriviallyNormedField 𝕜] {E : Type u_2} [inst_1 : NormedAddCommGroup E]\n  [inst_2 : NormedSpace 𝕜 E] {F : Type u_3} [inst_3 : NormedAddCommGroup F] [inst_4 : NormedSpace 𝕜 F] {G : Type u_4}\n  [inst_5 : NormedAddCommGroup G] [inst_6 : NormedSpace 𝕜 G] {s : Set E} {t : Set F}\n  {q : F → FormalMultilinearSeries 𝕜 F G} {p : E → FormalMultilinearSeries 𝕜 E F} {n : WithTop ℕ∞} {g : F → G}\n  {f : E → F},\n  HasFTaylorSeriesUpToOn n g q t →\n    HasFTaylorSeriesUpToOn n f p s..."
    }
  ]
}

